            type: 'string',
            enum: ['add', 'subtract', 'multiply', 'divide'],
            description: 'The arithmetic operation to perform.',
          },
        },
        required: ['a', 'b', 'operation'],
        additionalProperties: false,
      },
    },
  ];
}

function isNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
